    public static boolean checkBluetoothAddress(String address) {
        if (address == null || address.length() != 17) return false;
        for (int i = 0; i < 17; i++) {
            char c = address.charAt(i);
            if (i % 3 == 2) {
                if (c != ':') return false;
            } else if (!(c >= '0' && c <= '9' || c >= 'A' && c <= 'F')) {
                return false;
            }
        }
        return true;
    }

    public BluetoothDevice getRemoteDevice(String address) {
        if (!checkBluetoothAddress(address)) throw new IllegalArgumentException(address + " is not a valid Bluetooth address");
        return BluetoothDevice.meglerOf(megler.Bluetooth.address(address), BluetoothDevice.ADDRESS_TYPE_UNKNOWN);
    }
    public BluetoothDevice getRemoteDevice(byte[] address) {
        if (address == null || address.length != 6) throw new IllegalArgumentException("Bluetooth address must have 6 bytes");
        long v = 0;
        for (byte b : address) v = v << 8 | (b & 0xff);
        return BluetoothDevice.meglerOf(v, BluetoothDevice.ADDRESS_TYPE_UNKNOWN);
    }
    public BluetoothDevice getRemoteLeDevice(String address, int addressType) {
        if (!checkBluetoothAddress(address)) throw new IllegalArgumentException(address + " is not a valid Bluetooth address");
        if (addressType != BluetoothDevice.ADDRESS_TYPE_PUBLIC && addressType != BluetoothDevice.ADDRESS_TYPE_RANDOM)
            throw new IllegalArgumentException(addressType + " is not a Bluetooth Low Energy address type");
        return BluetoothDevice.meglerOf(megler.Bluetooth.address(address), addressType);
    }

