    public boolean startLeScan(LeScanCallback callback) { return startLeScan(null, callback); }

    /**
     * Android 4.3's scan: every advertisement (or those with all the service UUIDs given) to callback.onLeScan with its raw
     * record, on the main thread, as Android's own wraps it in a scan of its BluetoothLeScanner.
     */
    public boolean startLeScan(final UUID[] serviceUuids, final LeScanCallback callback) {
        megler.Bluetooth.enforce("android.permission.BLUETOOTH_SCAN", "BluetoothAdapter.startLeScan");
        if (callback == null) return false;
        BluetoothLeScanner scanner = getBluetoothLeScanner();
        if (scanner == null) return false;
        synchronized (mLeScans) {
            if (mLeScans.containsKey(callback)) return false;
            ScanCallback wrapper = new ScanCallback() {
                @Override public void onScanResult(int callbackType, ScanResult result) {
                    ScanRecord record = result.getScanRecord();
                    if (serviceUuids != null && serviceUuids.length > 0) {
                        List<ParcelUuid> have = record != null ? record.getServiceUuids() : null;
                        if (have == null) return;
                        for (UUID u : serviceUuids)
                            if (!have.contains(new ParcelUuid(u))) return;
                    }
                    callback.onLeScan(result.getDevice(), result.getRssi(), record != null ? record.getBytes() : new byte[0]);
                }
            };
            mLeScans.put(callback, wrapper);
            scanner.startScan(new ArrayList<ScanFilter>(), new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(), wrapper);
        }
        return true;
    }

    public void stopLeScan(LeScanCallback callback) {
        ScanCallback wrapper;
        synchronized (mLeScans) { wrapper = mLeScans.remove(callback); }
        BluetoothLeScanner scanner = getBluetoothLeScanner();
        if (wrapper != null && scanner != null) scanner.stopScan(wrapper);
    }

    /**
     * The radio's state changed (megler.Bluetooth's thread): ACTION_STATE_CHANGED as Android sends it, to the receivers
     * registered for it, on the main thread -- through STATE_TURNING_ON before STATE_ON, STATE_TURNING_OFF before
     * STATE_OFF. Off, the app's scans end, as Android's end with the adapter.
     */
    public static void meglerState(int radio) {
        int now = stateOf(radio), before;
        synchronized (BluetoothAdapter.class) {
            before = sTold;
            if (before < 0) before = now == STATE_ON ? STATE_OFF : STATE_ON;
            sTold = now;
        }
        if (before == now) return;
        if (now != STATE_ON) BluetoothLeScanner.meglerRadioOff();
        int between = now == STATE_ON ? STATE_TURNING_ON : STATE_TURNING_OFF;
        android.content.Context app = megler.AppRunner.application();
        broadcast(app, between, before);
        broadcast(app, now, between);
        // (An app's request to turn it on, which showed the phone's settings, has its answer.)
        if (now == STATE_ON) megler.Bluetooth.radioOn();
    }

    private static void broadcast(android.content.Context app, int state, int previous) {
        Intent i = new Intent(ACTION_STATE_CHANGED);
        i.putExtra(EXTRA_STATE, state);
        i.putExtra(EXTRA_PREVIOUS_STATE, previous);
        megler.Broadcasts.send(app, i);
    }

    /** What the app has been told, for the first broadcast's EXTRA_PREVIOUS_STATE: what it saw when it first asked. */
    static void meglerSeen(int state) {
        synchronized (BluetoothAdapter.class) { if (sTold < 0) sTold = state; }
    }
